window.SBL_LESSONS.RC01 = {
  id: 'RC01',
  topicNumber: 1,
  topicTitle: 'Global trends in consumption',
  title: 'Global, continental and regional progress towards poverty reduction',
  href: '/geography/paper-1/core-3/t1-global-trends/l1-global',
  syllabusFocus: 'Global, continental and regional progress towards poverty reduction, including the growth of the "new global middle class" and its social, economic, environmental and political implications.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'Types of poverty', request: 'Explain the difference between absolute poverty, relative poverty, income poverty and extreme poverty' },
    { label: 'The new global middle class', request: 'Explain what is meant by the "new global middle class" and why it is growing' },
    { label: 'Growth trends', request: 'Explain how the size of the global middle class is projected to change between 2009 and 2030' },
    { label: 'Asia\u2019s role', request: 'Explain why Asia is expected to dominate future middle-class growth' },
    { label: 'Social implications', request: 'Explain the social implications of a growing global middle class' },
    { label: 'Economic implications', request: 'Explain the economic implications of a growing global middle class' },
    { label: 'Environmental implications', request: 'Explain the environmental implications of a growing global middle class' },
    { label: 'Political implications', request: 'Explain the political implications of a growing global middle class' }
  ],
  checklist: [
    'I can distinguish absolute, relative, income and extreme poverty.',
    'I can describe global progress towards poverty reduction.',
    'I can define the "new global middle class".',
    'I can recall the projected growth in the global middle class to 2030.',
    'I can explain why Asia is central to this growth.',
    'I can explain social implications of a growing middle class.',
    'I can explain economic implications of a growing middle class.',
    'I can explain environmental implications of a growing middle class.',
    'I can explain political implications of a growing middle class.'
  ],
  readinessQuestions: [
    'Explain the difference between absolute poverty and relative poverty.',
    'Why is the growth of the global middle class concentrated in Asia?',
    'Give one environmental implication of a growing global middle class.',
    'Give one political implication of a growing global middle class.',
    'Explain why a growing middle class does not automatically mean an equally growing ecological footprint for every person within it.'
  ],
  quiz: [
    { q: 'Absolute poverty is best defined as:', options: ['Having less income than others in your society', 'A severe deprivation of basic human needs, measured against a fixed threshold regardless of place', 'Any household earning below the national average', 'A country with a low GDP per capita'], correct: 1, explain: 'Absolute poverty refers to a severe lack of basic necessities (food, water, shelter, sanitation), measured against a fixed minimum standard that does not vary by country or society.', misconception: 'Absolute poverty is sometimes confused with relative poverty; the key distinguishing feature of "absolute" is that the threshold is fixed and comparable across places, not relative to local living standards.', tag: 'Types of poverty' },
    { q: 'Relative poverty is best defined as:', options: ['Having income below a fixed international threshold', 'Having significantly less income or resources than the typical standard of living in one\u2019s own society', 'Living without access to clean water', 'A term used only in low-income countries'], correct: 1, explain: 'Relative poverty is measured against the standard of living typical in a specific society, meaning the threshold varies from country to country.', misconception: 'Relative poverty is sometimes assumed to only apply to LICs; in fact, it is a measure commonly used to assess inequality within wealthy, high-income countries too.', tag: 'Types of poverty' },
    { q: 'Extreme poverty is most closely associated with:', options: ['Any household with below-average national income', 'Living below an internationally defined minimum income threshold, historically referenced as around $1.90–$2.15 a day', 'A lack of access to luxury goods', 'A measure only used for entire countries, never individuals'], correct: 1, explain: 'Extreme poverty is typically defined using an international poverty line (an income threshold updated periodically by organisations such as the World Bank), representing the most severe form of income poverty.', misconception: 'Extreme poverty is sometimes used loosely to mean "very poor" without reference to any specific measurable threshold, when it actually has a defined, internationally comparable definition.', tag: 'Types of poverty' },
    { q: 'The "new global middle class" refers to:', options: ['A fixed group of wealthy families that has existed for centuries', 'A rapidly growing global population group with rising disposable income, increasingly concentrated in emerging economies', 'Only the middle class of high-income countries', 'A term with no real economic significance'], correct: 1, explain: 'The "new global middle class" describes the fast-growing population group, increasingly located in emerging and developing economies, who have gained enough disposable income to consume beyond basic needs.', misconception: 'The global middle class is sometimes assumed to be concentrated in traditionally wealthy HICs, when most of its recent and projected future growth is actually occurring in emerging economies, especially in Asia.', tag: 'The new global middle class' },
    { q: 'Projections suggest the size of the global middle class will grow from approximately 1.8 billion in 2009 to around:', options: ['2 billion by 2030', '3.2 billion by 2020 and 4.9 billion by 2030', '10 billion by 2030', 'It is projected to shrink after 2020'], correct: 1, explain: 'Projections estimate the global middle class growing from around 1.8 billion in 2009 to roughly 3.2 billion by 2020, and approximately 4.9 billion by 2030.', misconception: 'The scale of this growth is sometimes underestimated; it represents nearly a tripling of the global middle-class population within about two decades.', tag: 'Growth trends' },
    { q: 'By 2030, Asia is projected to represent approximately what share of the global middle-class population?', options: ['10%', '28%', '66%', '95%'], correct: 2, explain: 'By 2030, Asia is projected to represent around 66% of the global middle-class population and roughly 59% of middle-class consumption, up sharply from 28% and 23% respectively in 2009.', misconception: 'It is sometimes assumed middle-class growth is evenly spread globally, when projections show it becoming very heavily concentrated in Asia specifically.', tag: 'Asia\u2019s role' },
    { q: 'A commonly cited social implication of a growing global middle class is that it:', options: ['Reduces political engagement everywhere', 'Is associated with growing support for democratic and moderate political participation', 'Automatically eliminates poverty within a country', 'Has no measurable effect on society'], correct: 1, explain: 'A growing, economically secure middle class is often associated with increased political participation and support for democratic, moderate political platforms, partly because they have a stronger stake in stable governance.', misconception: 'Social implications of middle-class growth are sometimes overlooked in favour of purely economic effects, but political and social participation is a well-documented consequence too.', tag: 'Social implications' },
    { q: 'A key economic implication of a growing middle class in a developing economy is that it can enable a shift towards:', options: ['Complete reliance on agricultural subsistence', 'Greater domestic consumption-driven growth, reducing reliance on export-driven growth alone', 'The elimination of all foreign trade', 'Reduced overall economic activity'], correct: 1, explain: 'As disposable incomes rise, a growing middle class can drive domestic consumption of goods and services, helping economies shift from relying solely on export-driven growth towards a more consumption-based model — as seen historically in South Korea and China.', misconception: 'Middle-class growth is sometimes framed only in terms of "more shopping," missing its broader structural economic significance in shifting a country\u2019s growth model.', tag: 'Economic implications' },
    { q: 'A key environmental implication of a growing global middle class is:', options: ['A guaranteed reduction in resource consumption', 'Increased consumption of resources and generally a higher ecological footprint compared to lower-income groups', 'No measurable environmental effect', 'A shift entirely towards plant-based diets worldwide'], correct: 1, explain: 'As disposable income rises, consumption of goods, resources, meat and dairy tends to increase, and the middle class generally has a higher ecological footprint than lower-income groups, contributing to greater overall resource use.', misconception: 'Environmental impact is sometimes assumed to be driven mainly by population growth alone; rising per-person consumption as incomes grow is an equally significant driver.', tag: 'Environmental implications' },
    { q: 'A political implication of a rapidly growing middle class in an emerging economy can be:', options: ['No change in expectations of government at all', 'Rising and evolving expectations for quality public services, which governments may struggle to meet', 'A guaranteed and immediate improvement in all public services', 'The complete disappearance of political parties'], correct: 1, explain: 'As middle-class expectations rise alongside economic growth, governments in emerging and developing economies can face pressure to provide better-quality public services, which their existing capacity may struggle to keep pace with.', misconception: 'It is sometimes assumed that economic growth automatically brings adequate public service improvement in step with rising expectations, when in practice government capacity can lag behind rapidly rising middle-class demands.', tag: 'Political implications' }
  ]
};

window.SBL_LESSONS.RC02 = {
  id: 'RC02',
  topicNumber: 1,
  topicTitle: 'Global trends in consumption',
  title: 'Measuring trends and patterns in resource consumption',
  href: '/geography/paper-1/core-3/t1-global-trends/l2-measuring',
  syllabusFocus: 'Measuring trends in resource consumption, including individual, national and global ecological footprints.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is an ecological footprint?', request: 'Explain what an ecological footprint is' },
    { label: 'What is a global hectare?', request: 'Explain what a global hectare is and why it is used' },
    { label: 'Ecological debtors and creditors', request: 'Explain the difference between an ecological debtor and an ecological creditor country' },
    { label: 'What is biocapacity?', request: 'Explain what biocapacity means' },
    { label: 'Calculating a footprint', request: 'Explain how an ecological footprint is calculated' },
    { label: 'Global patterns in footprints', request: 'Describe global patterns in the size of ecological footprints' },
    { label: 'Limitations of the footprint', request: 'Explain some limitations of the ecological footprint as a measure' }
  ],
  checklist: [
    'I can define ecological footprint.',
    'I can define a global hectare.',
    'I can define biocapacity.',
    'I can distinguish an ecological debtor from an ecological creditor.',
    'I can explain how my own ecological footprint is calculated.',
    'I can describe global patterns in the size of ecological footprints.',
    'I can link footprint size to income and consumption patterns.',
    'I can explain a limitation of the ecological footprint as a measure.'
  ],
  ibQuestions: [
    {
      question: 'Suggest one way in which greater use of renewable energy can: (i) decrease the size of a nation\u2019s ecological footprint; (ii) increase the size of a nation\u2019s ecological footprint.',
      marks: 4,
      markScheme: '(i) Decrease the size of a nation’s ecological footprint\n\nAward [1] for a valid way and [1] for development linked to decrease in ecological footprint (land/sea/vegetation).\n\nValid possibilities include:\n- less need for fossil fuels like coal which means less land required to obtain energy\n- less need for fossil fuels like oil which means less land/sea polluted by oil spills\n- more energy is produced by wind farms which means less nuclear waste / land contamination issues\n- renewable energy is produced without the burning of fossil fuels and the resultant emissions, so less land/vegetation/ocean is required to absorb greenhouse gases.\n\nFor example: Decreased use of fossil fuels because of switching energy sources [1] decreases the amount of land required for mining or disposal of waste [1].\n\n(ii) Increase the size of a nation’s ecological footprint\n\nAward [1] for a valid way and [1] for development linked to increase in ecological footprint.\n\nValid possibilities include:\n- solar and wind farms require large areas of land and these can reduce the natural vegetation of an area\n- valleys drowned for HEP reservoirs which reduces vegetation and covers areas of soil.\n- use of electric cars increases demand for rare minerals which increases land destroyed by mining.\n\nFor example: Greater use of biofuels requires palm oil cultivation [1] across extensive areas of land [1].'
    }
  ],
  readinessQuestions: [
    'What is a global hectare and why is it a useful unit of measurement?',
    'Explain the difference between an ecological debtor country and an ecological creditor country.',
    'Give one reason why high-income countries tend to have larger ecological footprints.',
    'Explain what biocapacity measures.',
    'Give one limitation of using the ecological footprint to compare countries.'
  ],
  quiz: [
    { q: 'An ecological footprint is best defined as:', options: ['The physical land area a country occupies', 'A measure of the amount of biologically productive land and water a population requires to produce the resources it consumes and absorb its waste', 'A measure of a country\u2019s total population', 'A measure of a country\u2019s GDP'], correct: 1, explain: 'The ecological footprint measures the biologically productive land and water area required to produce the resources a population consumes and absorb the waste it generates, expressed in global hectares.', misconception: 'The ecological footprint is sometimes confused with a country\u2019s actual physical land area, when it is a demand-based measure of resource use, not a measure of territory.', tag: 'What is an ecological footprint?' },
    { q: 'A global hectare (gha) is:', options: ['A unit measuring exactly one hectare of any land, regardless of productivity', 'A standardised unit representing one hectare of biologically productive land or water with world-average productivity, allowing comparison across different ecosystem types', 'A unit only used to measure forest land', 'A measure of a country\u2019s population density'], correct: 1, explain: 'A global hectare standardises different types of land and water (cropland, forest, fishing grounds, etc.) using world-average productivity, allowing meaningful comparison of resource use across very different ecosystems.', misconception: 'It is sometimes assumed a "global hectare" is simply any hectare of land; the key feature is that it is adjusted to a standardised world-average productivity so that different land types can be compared fairly.', tag: 'What is a global hectare?' },
    { q: 'Biocapacity refers to:', options: ['The total resources a country consumes', 'The capacity of an area\u2019s ecosystems to produce useful biological materials and absorb waste generated by humans', 'A country\u2019s total industrial output', 'The number of protected nature reserves in a country'], correct: 1, explain: 'Biocapacity is the capacity of a given area\u2019s ecosystems to generate a renewable and ongoing supply of biological resources and to absorb the waste generated by human activity.', misconception: 'Biocapacity is sometimes confused with the ecological footprint; footprint measures demand for resources, while biocapacity measures the supply/capacity available to meet that demand.', tag: 'What is biocapacity?' },
    { q: 'An "ecological debtor" country is one where:', options: ['The population\u2019s ecological footprint exceeds the biocapacity available within that country', 'The country has more biocapacity than its population uses', 'The country has no ecological footprint at all', 'The country has eliminated all resource consumption'], correct: 0, explain: 'An ecological debtor country consumes resources at a rate exceeding its own biocapacity, meaning it relies on resources or ecological services from elsewhere (or draws down natural capital) to sustain its consumption.', misconception: 'Ecological debtor and creditor status is sometimes confused with financial wealth; a country can be economically wealthy yet ecologically "in debt" if its footprint exceeds its available biocapacity.', tag: 'Ecological debtors and creditors' },
    { q: 'An "ecological creditor" country is one where:', options: ['The population\u2019s footprint exceeds available biocapacity', 'The country\u2019s available biocapacity exceeds its population\u2019s ecological footprint', 'The country has no natural resources', 'The country imports all of its food'], correct: 1, explain: 'An ecological creditor country has more biocapacity available than its population\u2019s ecological footprint uses, meaning it has an ecological reserve rather than a deficit.', misconception: 'Ecological creditor status is sometimes assumed to only apply to very large countries; it actually depends on the balance between a specific population\u2019s consumption and the biocapacity available within its own territory, regardless of overall country size.', tag: 'Ecological debtors and creditors' },
    { q: 'An individual\u2019s ecological footprint is typically calculated based on:', options: ['Their age alone', 'Their consumption of food, housing, transport, goods and services, and the resulting land/water demand and waste', 'Only the size of their house', 'A single fixed number applied equally to everyone globally'], correct: 1, explain: 'An individual footprint is calculated by converting consumption across categories such as food, housing, transport, goods and services into the equivalent land and water area (in global hectares) required to support that consumption and absorb the resulting waste.', misconception: 'It is sometimes assumed the ecological footprint is a single simple statistic unrelated to personal lifestyle choices, when it is actually built up from multiple everyday consumption categories.', tag: 'Calculating a footprint' },
    { q: 'Global patterns generally show that ecological footprints are:', options: ['Identical across all countries regardless of income', 'Typically larger in higher-income countries with higher levels of consumption', 'Always largest in the lowest-income countries', 'Unrelated to a country\u2019s level of economic development'], correct: 1, explain: 'Higher-income countries generally have larger per-capita ecological footprints, reflecting higher levels of consumption of goods, energy, food and services.', misconception: 'Footprint size is sometimes assumed to correlate with population size alone; per-capita consumption patterns linked to income are actually the stronger driver of footprint size differences between countries.', tag: 'Global patterns in footprints' },
    { q: 'As a country becomes richer and its middle class grows, its ecological footprint would generally be expected to:', options: ['Decrease automatically', 'Increase, reflecting higher consumption of resources, goods and services', 'Stay completely unchanged', 'Become impossible to measure'], correct: 1, explain: 'As incomes rise and consumption of goods, food, energy and services increases (as seen with a growing middle class), a country or population\u2019s ecological footprint would generally be expected to rise.', misconception: 'This directly links back to the previous lesson\u2019s environmental implications of a growing middle class \u2014 rising consumption is the underlying driver of a rising footprint, not simply population growth.', tag: 'Global patterns in footprints' },
    { q: 'A recognised limitation of the ecological footprint as a measure is that it:', options: ['Perfectly and precisely accounts for every environmental impact', 'Simplifies complex environmental impacts into a single number and may not fully capture all forms of environmental degradation, such as biodiversity loss or pollution toxicity', 'Cannot be calculated for any country', 'Only applies to wealthy countries'], correct: 1, explain: 'While useful for comparison, the ecological footprint simplifies many complex environmental pressures into a single land-area-based number, and does not fully capture impacts such as biodiversity loss, toxic pollution, or water quality degradation.', misconception: 'The ecological footprint is sometimes treated as a complete, all-encompassing measure of environmental impact, when geographers recognise it as a useful but simplified indicator with real limitations.', tag: 'Limitations of the footprint' },
    { q: 'If every country\u2019s population consumed resources at the same rate as a high-footprint HIC, current global biocapacity would most likely be:', options: ['More than sufficient to meet demand indefinitely', 'Insufficient, since global demand would exceed the Earth\u2019s available biocapacity', 'Completely unaffected, since biocapacity is limitless', 'Irrelevant, since ecological footprint has no connection to biocapacity'], correct: 1, explain: 'If global consumption matched the high per-capita footprints typical of high-income countries, total global demand would exceed the Earth\u2019s available biocapacity, a situation often summarised by the idea of needing "multiple Earths" to sustain such consumption levels.', misconception: 'It is sometimes assumed footprint and biocapacity comparisons only matter at a national scale; extending the comparison globally illustrates the core sustainability concern behind this concept.', tag: 'Global patterns in footprints' }
  ]
};

window.SBL_LESSONS.RC03 = {
  id: 'RC03',
  topicNumber: 1,
  topicTitle: 'Global trends in consumption',
  title: 'Patterns and trends in the global availability and consumption of water',
  href: '/geography/paper-1/core-3/t1-global-trends/l3-patterns-and',
  syllabusFocus: 'An overview of global patterns and trends in the availability and consumption of water, including embedded water in food and manufactured goods.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'Global water consumption patterns', request: 'Describe global patterns of water consumption' },
    { label: 'Water stress vs water scarcity', request: 'Explain the difference between water stress and water scarcity' },
    { label: 'Uses of water', request: 'Explain the main global uses of water: agricultural, industrial and domestic' },
    { label: 'What is embedded water?', request: 'Explain what embedded (virtual) water means' },
    { label: 'Embedded water in food', request: 'Explain how much embedded water is in different foods' },
    { label: 'Regional water availability', request: 'Describe regional patterns in water availability' },
    { label: 'Why water consumption varies', request: 'Explain why water consumption varies so much between countries' }
  ],
  checklist: [
    'I can describe global patterns of water consumption.',
    'I can distinguish water stress from water scarcity.',
    'I can identify the main global uses of water.',
    'I can explain that agriculture is the largest global water user.',
    'I can define embedded (virtual) water.',
    'I can give an example of embedded water in food.',
    'I can describe regional patterns in water availability.',
    'I can explain why water consumption varies between countries.'
  ],
  ibQuestions: [
    {
      question: 'Describe what is meant by \u201cembedded water\u201d.',
      marks: 2,
      markScheme: 'Water resources that are used in the production of food and manufactured goods in one country/place [1] that are transferred to other, often water scarce, countries or regions via trading [1].'
    }
  ],
  readinessQuestions: [
    'What proportion of global water use is typically used for agriculture?',
    'Explain the difference between water stress and water scarcity.',
    'What is meant by "embedded water"?',
    'Give an example of a food or product with a high embedded water footprint.',
    'Explain one reason why water consumption per person varies so much between countries.'
  ],
  quiz: [
    { q: 'Globally, the largest single use of freshwater is for:', options: ['Domestic household use', 'Agriculture', 'Industrial manufacturing', 'Golf courses and leisure facilities'], correct: 1, explain: 'Agriculture, particularly irrigation, accounts for the largest share of global freshwater withdrawal, commonly estimated at around 70% worldwide.', misconception: 'Domestic use is sometimes assumed to be the largest consumer of water because it is the most visible in everyday life, when agriculture is actually the dominant global user by a wide margin.', tag: 'Uses of water' },
    { q: 'Water stress refers to:', options: ['A complete absence of any water resources', 'A situation where demand for water approaches or exceeds the available supply, straining resources', 'A psychological condition unrelated to water supply', 'A measure only used for drought-prone deserts'], correct: 1, explain: 'Water stress describes a situation where demand for water is high relative to available supply, straining water resources even if some water remains available.', misconception: 'Water stress is sometimes confused with total water scarcity (an absolute shortage); stress describes a growing strain on resources, which can occur even in areas that are not yet in absolute crisis.', tag: 'Water stress vs water scarcity' },
    { q: 'Water scarcity, as distinct from water stress, more specifically refers to:', options: ['A mild inconvenience with no real consequences', 'Insufficient water resources to meet demand, which can be physical (not enough water exists) or economic (infrastructure fails to deliver available water)', 'A term identical in meaning to water stress with no distinction', 'A condition that only occurs in high-income countries'], correct: 1, explain: 'Water scarcity describes a more severe insufficiency of water to meet demand, and can be split into physical scarcity (the resource genuinely does not exist in sufficient quantity) and economic scarcity (water exists but infrastructure/investment fails to make it accessible).', misconception: 'Water stress and water scarcity are sometimes used completely interchangeably; while related, scarcity generally implies a more severe and specific shortfall, and can usefully be split into physical versus economic causes.', tag: 'Water stress vs water scarcity' },
    { q: 'Embedded (or virtual) water refers to:', options: ['Water that is physically stored underground', 'The total volume of water used throughout the production process of a food or manufactured good', 'Water used only in bottled drinking water production', 'A term with no real practical use'], correct: 1, explain: 'Embedded water (also called virtual water) is the total volume of water used at every stage of producing a good, from raw materials through to the finished product, even though this water is not visibly present in the final item.', misconception: 'Embedded water is sometimes assumed to only refer to water literally contained within a product (like a drink), when it actually accounts for water used throughout the entire production process, however "invisible" in the final item.', tag: 'What is embedded water?' },
    { q: 'Which of these products typically has a very high embedded water footprint?', options: ['A kilogram of vegetables', 'A kilogram of beef', 'A litre of tap water', 'A single sheet of paper'], correct: 1, explain: 'Beef production has one of the highest embedded water footprints of any common food, due to the large volumes of water required to grow feed crops and support livestock over their lifetime.', misconception: 'People sometimes assume a product\u2019s embedded water footprint is proportional to how "watery" it looks or feels, when in fact it depends on the full water used throughout production, which can be very high for foods like beef despite containing relatively little liquid water themselves.', tag: 'Embedded water in food' },
    { q: 'Trading goods with high embedded water content between countries effectively means:', options: ['No water is actually being transferred anywhere', 'Water resources are indirectly being transferred from the producing country to the consuming country', 'Only physical bottled water can be considered a water transfer', 'Embedded water has no relevance to international trade'], correct: 1, explain: 'When a country exports goods with high embedded water content (such as agricultural products), it is effectively exporting water resources indirectly, even though no physical water crosses the border in visible form.', misconception: 'International water transfer is sometimes thought of only in terms of physical water pipelines or bottled water exports, overlooking the much larger indirect transfer of water embedded within traded goods.', tag: 'What is embedded water?' },
    { q: 'Regions such as the Middle East and North Africa are generally characterised by:', options: ['Abundant freshwater availability relative to demand', 'High levels of water stress or scarcity due to low rainfall and high demand', 'No agricultural water use at all', 'Complete self-sufficiency in water resources'], correct: 1, explain: 'The Middle East and North Africa region generally faces significant water stress or scarcity due to a combination of low and unreliable rainfall, high evaporation rates, and growing demand from agriculture, industry and population growth.', misconception: 'Regional water patterns are sometimes assumed to be uniform across similarly-sized areas, but climate, geology and demand differences create very significant regional variation in water stress.', tag: 'Regional water availability' },
    { q: 'A region with high rainfall, low population density and limited industrial water demand, such as the Amazon Basin, would typically be characterised by:', options: ['Severe water scarcity', 'Relative water abundance compared to demand', 'No water resources at all', 'The highest levels of water stress in the world'], correct: 1, explain: 'Regions like the Amazon Basin, with high rainfall and comparatively lower population and industrial demand relative to supply, generally experience relative water abundance rather than stress or scarcity.', misconception: 'Global water issues are sometimes assumed to be universal, when large parts of the world actually have relative water abundance; water stress is highly geographically uneven.', tag: 'Regional water availability' },
    { q: 'A country with a growing, increasingly affluent middle class would generally be expected to see its water consumption:', options: ['Decrease, as wealthier populations use less water', 'Increase, partly due to rising demand for water-intensive foods such as meat and dairy, and increased domestic/industrial use', 'Remain completely unchanged regardless of income growth', 'Become entirely unrelated to diet or lifestyle'], correct: 1, explain: 'As incomes rise, water consumption tends to increase both directly (domestic and industrial use) and indirectly (through embedded water in more water-intensive diets, such as increased meat and dairy consumption).', misconception: 'This links back to earlier lessons on the growing middle class and changing diets \u2014 rising affluence tends to increase both direct and embedded water demand, not reduce it.', tag: 'Why water consumption varies' },
    { q: 'Overall, global patterns of water availability and consumption illustrate that water issues are best understood as:', options: ['A single, uniform global problem with identical causes everywhere', 'The result of an interaction between physical water availability (climate, geology) and human demand factors (population, development, diet)', 'Entirely determined by rainfall alone, with no human influence', 'Unrelated to any other resource consumption topic'], correct: 1, explain: 'Global water patterns result from the interaction between physical factors (such as climate and geology determining natural water availability) and human factors (such as population size, economic development and dietary patterns driving demand) \u2014 a combination that recurs throughout this unit.', misconception: 'Water availability is sometimes seen purely as a physical/climatic issue, when human demand factors are equally central to understanding real-world water stress and scarcity patterns.', tag: 'Regional water availability' }
  ]
};

